"""
Chained log: a diary that's only appended to at the end and where you can't
tamper with an old line without it showing.

The trick: each line stores a fingerprint (a long number computed from its
own content) and also the previous line's fingerprint. If someone changes a
comma in line 3, its fingerprint stops matching and every line below it is
left dangling. It's the same thing a blockchain does, minus the blockchain.

Hard rule: personal data NEVER goes in here. It stores what was done, what
it cost, and who asked for it, not the content of the query.
"""

import hashlib
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

from redactor import hay_datos_personales

CARPETA = Path(__file__).resolve().parent
FICHERO = CARPETA / "registro.jsonl"
SEMILLA = "0" * 64  # Line zero's imaginary fingerprint.

# Fields that don't get checked because they're fingerprints, not anyone's text.
CAMPOS_TECNICOS = {"huella", "anterior", "cuando"}


def _huella(texto):
    """SHA-256: turns any text into 64 fixed letters and numbers."""
    return hashlib.sha256(texto.encode("utf-8")).hexdigest()


def _ultima_huella():
    if not FICHERO.exists():
        return SEMILLA
    ultima = SEMILLA
    # utf-8-sig: if Notepad saved the file with an invisible marker
    # at the start, that marker gets ignored instead of crashing.
    with FICHERO.open("r", encoding="utf-8-sig") as fichero:
        for linea in fichero:
            linea = linea.strip()
            if linea:
                ultima = json.loads(linea)["huella"]
    return ultima


def _revisa_que_no_haya_datos_personales(evento):
    for clave, valor in evento.items():
        if clave in CAMPOS_TECNICOS:
            continue
        if isinstance(valor, str) and hay_datos_personales(valor):
            raise ValueError(
                "Field '%s' carries unmasked personal data. "
                "It doesn't get written to the log." % clave
            )


def apunta(evento):
    """Adds a line to the end of the diary. Nothing is ever edited or deleted."""
    _revisa_que_no_haya_datos_personales(evento)

    linea = {"cuando": datetime.now(timezone.utc).isoformat(timespec="seconds")}
    linea["anterior"] = _ultima_huella()
    linea.update(evento)
    linea["huella"] = _huella(json.dumps(linea, sort_keys=True, ensure_ascii=False))

    with FICHERO.open("a", encoding="utf-8") as fichero:
        fichero.write(json.dumps(linea, ensure_ascii=False) + "\n")
    return linea


def verifica():
    """
    Walks the diary top to bottom and checks nobody has touched anything.
    Returns (True/False, message).
    """
    if not FICHERO.exists():
        return True, "The diary is empty: nothing to verify yet."

    anterior = SEMILLA
    total = 0

    with FICHERO.open("r", encoding="utf-8-sig") as fichero:
        for numero, linea in enumerate(fichero, start=1):
            linea = linea.strip()
            if not linea:
                continue
            total += 1

            try:
                guardado = json.loads(linea)
            except json.JSONDecodeError:
                return False, "Line %d: no longer valid JSON. It's been broken." % numero

            huella = guardado.pop("huella", None)

            if guardado.get("anterior") != anterior:
                return False, (
                    "Line %d: doesn't link to the previous one. Either a line "
                    "is missing or the order has changed." % numero
                )

            recalculada = _huella(json.dumps(guardado, sort_keys=True, ensure_ascii=False))
            if recalculada != huella:
                return False, (
                    "Line %d: content doesn't match its fingerprint. "
                    "Someone edited this line." % numero
                )

            anterior = huella

    return True, "%d lines verified. The chain is intact." % total


def ultimas(cuantas=5):
    """The diary's last lines, for a quick look."""
    if not FICHERO.exists():
        return []
    texto = FICHERO.read_text(encoding="utf-8-sig")
    lineas = []
    for cruda in texto.splitlines():
        if not cruda.strip():
            continue
        try:
            lineas.append(json.loads(cruda))
        except json.JSONDecodeError:
            lineas.append({"tipo": "UNREADABLE", "cuando": "?"})
    return lineas[-cuantas:]


if __name__ == "__main__":
    correcto, mensaje = verifica()
    print(("OK      " if correcto else "ALARM   ") + mensaje)
    for linea in ultimas(5):
        print("  %s  %-9s  %s" % (
            linea.get("cuando", "?"),
            linea.get("tipo", "?"),
            linea.get("accion") or linea.get("modelo") or "",
        ))
    sys.exit(0 if correcto else 1)
